import * as THREE from 'three';
const STORAGE='shankaranarayana.photo-poses.v1';
export function installPhotoAlignment({camera,photos,enter,release,getCurrentPhoto}){
 const $=id=>document.getElementById(id);let entries=new Map(),saved=new Map(),active=false,selected=null;
 const panel=document.createElement('section');panel.id='photo-alignment';panel.hidden=true;panel.className='panel';panel.setAttribute('aria-label','Align a photograph');
 panel.innerHTML=`<div class="panel-title"><h3>Align a photo</h3><button id="align-close" aria-label="Close photo alignment">×</button></div>
 <details open id="align-tools"><summary>Photo &amp; camera controls</summary>
 <label>Photo<select id="align-select"></select></label><label class="align-file">Open local photos<input id="align-files" type="file" accept="image/jpeg,image/png,image/webp" multiple></label>
 <p class="align-help">Match the camera to the photo. Drag to look; scroll or use WASD to move. Buttons make fine adjustments. Photo fills the view; edges may crop.</p>
 <label>Photo opacity<input id="align-opacity" type="range" min="0" max="100" value="45"></label>
 <label>Field of view <output id="align-fov-value"></output><input id="align-fov" type="range" min="20" max="110" step=".1"></label>
 <label>Move by<select id="align-step"><option value=".1">10 cm</option><option value=".25" selected>25 cm</option><option value="1">1 metre</option></select></label>
 <div class="align-grid" id="align-moves"><button data-shift="forward">Forward</button><button data-shift="back">Back</button><button data-shift="left">Left</button><button data-shift="right">Right</button><button data-shift="up">Higher</button><button data-shift="down">Lower</button><button data-turn="left">Look left</button><button data-turn="right">Look right</button><button data-turn="up">Look up</button><button data-turn="down">Look down</button></div>
 <label>Notes<textarea id="align-notes" rows="2" maxlength="1000" placeholder="Where were you standing? What should change?"></textarea></label>
 <div class="align-actions"><button id="align-suggested">Suggested view</button><button id="align-restore">Restore saved</button></div></details>
 <div class="align-actions"><button id="align-toggle-overlay">Hide photo</button><button id="align-save">Save pose</button><button id="align-export">Export JSON</button><label class="align-file">Import JSON<input id="align-import" type="file" accept="application/json,.json"></label></div>
 <p id="align-status" role="status"></p><p class="align-help">Photos stay on this device. Saves are local to this browser and site. Export JSON to share the alignments; it contains no photo pixels.</p>`;
 document.body.append(panel);
 const overlay=document.createElement('img');overlay.id='alignment-overlay';overlay.alt='Reference photo overlay';overlay.hidden=true;document.body.append(overlay);
 const button=document.createElement('button');button.id='align-photo';button.textContent='Align photo';$('photos').append(button);
 const status=text=>$('align-status').textContent=text;
 overlay.onload=()=>{$('align-save').disabled=false;};
 overlay.onerror=()=>{$('align-save').disabled=true;status('Photo could not be opened. Choose another file.');};
 const valid=r=>r&&typeof r.id==='string'&&r.id.length<200&&typeof r.filename==='string'&&r.filename.length<300&&r.camera&&['position','quaternion'].every(k=>Array.isArray(r.camera[k])&&r.camera[k].length===(k==='position'?3:4)&&r.camera[k].every(Number.isFinite))&&r.camera.position.every(v=>Math.abs(v)<1000)&&Math.abs(Math.hypot(...r.camera.quaternion)-1)<.01&&Number.isFinite(r.camera.verticalFov)&&r.camera.verticalFov>=20&&r.camera.verticalFov<=110;
 try{const records=JSON.parse(localStorage.getItem(STORAGE)||'[]');if(Array.isArray(records))for(const r of records)if(valid(r))saved.set(r.id,r);}catch{}
 function persist(){try{localStorage.setItem(STORAGE,JSON.stringify([...saved.values()]));return true;}catch{return false;}}
 for(const [key,p] of Object.entries(photos)){const label=[...$('photo-select').options].find(o=>o.value===key)?.textContent||p.caption||key;entries.set('asset:'+key,{id:'asset:'+key,filename:p.url,url:'./assets/'+p.url,label,photo:p});}
 function options(){const select=$('align-select');select.replaceChildren();for(const e of entries.values()){const o=document.createElement('option');o.value=e.id;o.textContent=e.label;select.append(o);}if(selected)select.value=selected.id;}
 function lens(){const f=Math.min(110,Math.max(20,camera.fov));camera.fov=f;camera.updateProjectionMatrix();$('align-fov').value=f;$('align-fov-value').value=f.toFixed(1)+'°';}
 function apply(record){camera.position.fromArray(record.camera.position);camera.quaternion.fromArray(record.camera.quaternion).normalize();camera.fov=record.camera.verticalFov;enter();lens();}
 function choose(id){selected=entries.get(id);$('align-save').disabled=true;overlay.src=selected.url;if(overlay.complete&&overlay.naturalWidth)$('align-save').disabled=false;overlay.style.opacity=$('align-opacity').value/100;$('align-notes').value=saved.get(id)?.notes||'';$('align-restore').disabled=!saved.has(id);$('align-suggested').disabled=!selected.photo;status(saved.has(id)?'Saved pose available. Restore it or save a new position.':'No saved pose yet.');}
 function close(){active=false;panel.hidden=true;overlay.hidden=true;document.body.classList.remove('aligning-photo');release();$('photos').hidden=false;$('align-photo').focus();}
 button.onclick=()=>{active=true;enter();panel.hidden=false;overlay.hidden=false;$('align-toggle-overlay').textContent='Hide photo';document.body.classList.add('aligning-photo');$('photos').hidden=true;$('settings').hidden=true;options();choose('asset:'+getCurrentPhoto());$('align-select').value=selected.id;lens();$('align-close').focus();};
 $('align-close').onclick=close;
 $('align-toggle-overlay').onclick=()=>{overlay.hidden=!overlay.hidden;$('align-toggle-overlay').textContent=overlay.hidden?'Show photo':'Hide photo';};
 $('align-select').onchange=e=>choose(e.target.value);
 $('align-opacity').oninput=e=>overlay.style.opacity=e.target.value/100;
 $('align-fov').oninput=e=>{camera.fov=+e.target.value;lens();};
 $('align-moves').onclick=e=>{const b=e.target.closest('button');if(!b)return;const step=+$('align-step').value;
  if(b.dataset.shift){const axes={forward:[0,0,-1],back:[0,0,1],left:[-1,0,0],right:[1,0,0],up:[0,1,0],down:[0,-1,0]};const v=new THREE.Vector3(...axes[b.dataset.shift]);if(!['up','down'].includes(b.dataset.shift))v.applyQuaternion(camera.quaternion);camera.position.addScaledVector(v,step);}
  else{const euler=new THREE.Euler().setFromQuaternion(camera.quaternion,'YXZ'),d=THREE.MathUtils.degToRad(2);if(b.dataset.turn==='left')euler.y+=d;if(b.dataset.turn==='right')euler.y-=d;if(b.dataset.turn==='up')euler.x+=d;if(b.dataset.turn==='down')euler.x-=d;euler.x=THREE.MathUtils.clamp(euler.x,-1.5,1.5);camera.quaternion.setFromEuler(euler);}enter();
 };
 $('align-suggested').onclick=()=>{const p=selected.photo;if(!p)return;camera.position.set(p.p[0],p.p[1]+1.62,p.p[2]);camera.lookAt(new THREE.Vector3(...p.target));camera.fov=p.fov||58;enter();lens();};
 $('align-save').onclick=()=>{if(!overlay.naturalWidth){status('Wait for the photo to finish loading.');return;}const p=camera.position,q=camera.quaternion;const record={id:selected.id,filename:selected.filename,sha256:selected.sha256||null,notes:$('align-notes').value,camera:{position:p.toArray(),quaternion:q.toArray(),direction:camera.getWorldDirection(new THREE.Vector3()).toArray(),verticalFov:camera.fov,aspect:camera.aspect},image:{width:overlay.naturalWidth,height:overlay.naturalHeight,fit:'cover'},viewport:{width:innerWidth,height:innerHeight},savedAt:new Date().toISOString()};saved.set(selected.id,record);$('align-restore').disabled=false;status(persist()?'Pose saved on this device. Export when ready to share.':'Saved for this session only. Browser storage is unavailable; export now.');};
 $('align-restore').onclick=()=>{const record=saved.get(selected.id);if(record){apply(record);$('align-notes').value=record.notes||'';status('Saved camera restored. Match at the original window shape for the same photo crop.');}};
 $('align-export').onclick=()=>{const data={schema:'shankaranarayana-photo-poses',version:1,coordinates:'Three.js world metres; Y up; camera position is eye position (not feet)',exportedAt:new Date().toISOString(),poses:[...saved.values()]};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='shankaranarayana-photo-poses.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status(`Exported ${saved.size} saved pose(s). Unsaved adjustments are not included.`);};
 $('align-files').onchange=async e=>{try{let last;for(const file of e.target.files){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>40*1024*1024)throw Error('Choose JPEG, PNG or WebP photos smaller than 40 MB.');const hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',await file.arrayBuffer()))].map(n=>n.toString(16).padStart(2,'0')).join('');const id='local:'+hash;const previous=entries.get(id);if(previous)URL.revokeObjectURL(previous.url);entries.set(id,{id,filename:file.name,label:file.name,url:URL.createObjectURL(file),sha256:hash});last=id;}options();if(last){choose(last);$('align-select').value=last;}}catch(err){status(err.message);}finally{e.target.value='';}};
 $('align-import').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>2*1024*1024)throw Error('Alignment file is too large.');const data=JSON.parse(await file.text());if(data.schema!=='shankaranarayana-photo-poses'||data.version!==1||!Array.isArray(data.poses)||data.poses.length>1000||!data.poses.every(valid))throw Error('This is not a valid photo-alignment export.');for(const r of data.poses)saved.set(r.id,{...r,notes:String(r.notes||'').slice(0,1000)});persist();choose(selected.id);status(`Imported ${data.poses.length} poses. Open matching local photos to restore their cameras.`);}catch(err){status(err.message);}finally{e.target.value='';}};
 return {get active(){return active;},close};
}
